import data from '../../../supabase/seed/data/fichas-gabi-2026-11-03.json';

/**
 * Gabi's ficha of a course as an authorized catalog fact (AGENTS.md, "Material
 * de Gabi"). Generated by scripts/generate-gabi-fichas-seed.mjs; it never
 * carries a price or the scholarship. Callers decide WHICH courses are shown
 * (focus + bonus candidates, active offerings only); this module only renders.
 */
interface FichaCourse {
  readonly manual_name: string;
  readonly offering_code: string | null;
  readonly academia: string;
  readonly clases: number | null;
  readonly evaluacion: string | null;
  readonly descripcion: string;
  readonly lo_mas_importante: readonly string[];
  readonly cliente_ideal: string;
  readonly combinalo_con: readonly string[];
}
interface FichaRoute {
  readonly name: string;
  readonly courses: ReadonlyArray<{ readonly manual_name: string; readonly offering_code: string | null }>;
  readonly argumento: string;
}

const COURSES = data.courses as unknown as readonly FichaCourse[];
const ROUTES = data.routes as unknown as readonly FichaRoute[];
const BY_CODE = new Map(COURSES.flatMap((course) => course.offering_code ? [[course.offering_code, course] as const] : []));

/** The fact id is the same for the backend registry and the model context. */
export const fichaFactIdV1 = (offeringCode: string): string => `offering:${offeringCode}:ficha:v1`;
export const FICHA_FACT_ID_PATTERN = /^offering:([a-z0-9_]+):ficha:v1$/u;
export const FICHA_FACT_MAX_CHARS = 1_200;

const fold = (value: string): string => value.normalize('NFD').replace(/\p{Diacritic}/gu, '').toLowerCase()
  .replace(/\([^)]*\)/gu, ' ').replace(/[^a-z0-9/\- ]+/gu, ' ').replace(/\s+/gu, ' ').trim();

/** Short forms the manual uses inside "Combinalo con" for a course, folded. */
const COMBINE_ALIASES: Readonly<Record<string, readonly string[]>> = {
  'publicidad en redes': ['publicidad_redes_sociales'], 'photoshop': ['diseno_photoshop'],
  'illustrator': ['diseno_illustrator'], 'coreldraw': ['diseno_corel_draw'],
  'e-commerce': ['introduccion_ecommerce'], 'ecommerce': ['introduccion_ecommerce'],
  'fotografia con celulares': ['fotografia_celulares_tiendas_online'],
  'influencers': ['influencers_creadores_contenidos'], 'catering': ['introduccion_catering'],
  'sushi': ['sushi_principiantes'], 'vino y maridaje': ['vino_cata_maridaje'],
  'organizador de eventos': ['organizador_eventos_sociales'], 'baby shower': ['organizacion_baby_shower'],
  'estetica integral': ['estetica_integral'], 'maquillaje': ['maquillaje_profesional'],
  'unas': ['unas_gelificadas'], 'depilacion definitiva': ['depilacion_definitiva'],
  'energia solar': ['energia_solar_fotovoltaica'], 'aires acondicionados': ['aires_acondicionados'],
  'camaras de seguridad': ['camaras_seguridad'], 'excel': ['excel_integral'], 'coaching': ['coaching_liderazgo'],
  'comunicacion interna': ['comunicacion_interna_empresas'], 'autocad': ['autocad_interiores'],
  'ingles': ['ingles_1'], 'ingles i': ['ingles_1'], 'ingles i y ii': ['ingles_1', 'ingles_2'],
  'ingles iii y iv': ['ingles_3', 'ingles_4'], 'ingles i a iv': ['ingles_1', 'ingles_2', 'ingles_3', 'ingles_4'],
  'pasteleria': ['introduccion_pasteleria_reposteria'], 'pasteleria/reposteria': ['introduccion_pasteleria_reposteria'],
  'electricista': ['electricista'], 'organizador profesional de eventos': ['organizador_eventos_sociales'],
};
const CODE_BY_FOLDED_NAME = new Map<string, readonly string[]>([
  ...COURSES.flatMap((course) => course.offering_code ? [[fold(course.manual_name), [course.offering_code]] as const] : []),
  ...Object.entries(COMBINE_ALIASES),
]);

/** "Combinalo con" entries of the ficha as offering codes; entries naming no mapped course are dropped. */
function combinaloCodes(ficha: FichaCourse): string[] {
  return ficha.combinalo_con.flatMap((entry) => entry.split(/[;:]/u).flatMap((part) => CODE_BY_FOLDED_NAME.get(fold(part)) ?? []));
}

/**
 * Courses the manual combines with a paid course: its "Combinalo con" plus every
 * career route containing it. The single source of the bonus permission (backend)
 * and of the candidates the model sees; the caller keeps only active offerings.
 */
export function fichaCombinationCodesV1(offeringCode: string): string[] {
  const ficha = BY_CODE.get(offeringCode);
  const fromRoutes = ROUTES.filter((route) => route.courses.some((course) => course.offering_code === offeringCode))
    .flatMap((route) => route.courses.flatMap((course) => course.offering_code ? [course.offering_code] : []));
  return [...new Set([...(ficha ? combinaloCodes(ficha) : []), ...fromRoutes])].filter((code) => code !== offeringCode);
}

export function fichaOfferingCodes(): readonly string[] {
  return [...BY_CODE.keys()];
}

export interface FichaFactOptionsV1 {
  /** Offering codes that exist in the active catalog; routes only name those. */
  readonly activeCodes: ReadonlySet<string>;
}

/**
 * One compact text (no class count, see below): what it is, what they see, who it is for, what combines
 * with it and the career routes it belongs to (as argument, never permission).
 * Returns null when the course has no ficha or is not active.
 */
export function fichaFactValueV1(offeringCode: string, options: FichaFactOptionsV1): string | null {
  const ficha = BY_CODE.get(offeringCode);
  if (!ficha || !options.activeCodes.has(offeringCode)) return null;
  const routes = ROUTES.flatMap((route) => {
    if (!route.courses.some((course) => course.offering_code === offeringCode)) return [];
    const names = route.courses.filter((course) => course.offering_code && options.activeCodes.has(course.offering_code))
      .map((course) => course.manual_name);
    return names.length >= 2 ? [`${route.name}: ${names.join(' + ')} (${route.argumento})`] : [];
  });
  const parts = (highlights: readonly string[], combine: readonly string[], routeLines: readonly string[]) => [
    ficha.descripcion,
    // The class count is deliberately not part of the fact: the catalog's own
    // duration fact is the authority and the manual's number may differ.
    ...(ficha.evaluacion ? [`Evaluación: ${ficha.evaluacion}.`] : []),
    ...(highlights.length ? [`Verá: ${highlights.join('; ')}.`] : []),
    `Cliente ideal: ${ficha.cliente_ideal}`,
    ...(combine.length ? [`Combínalo con: ${combine.join(', ')}.`] : []),
    ...(routeLines.length ? [`Rutas de carrera (solo argumento): ${routeLines.join(' | ')}`] : []),
  ].join(' ');
  let highlights = [...ficha.lo_mas_importante];
  let combine = [...ficha.combinalo_con];
  let routeLines = routes;
  let text = parts(highlights, combine, routeLines);
  while (text.length > FICHA_FACT_MAX_CHARS && (routeLines.length > 1 || highlights.length > 2 || combine.length > 2)) {
    if (routeLines.length > 1) routeLines = routeLines.slice(0, -1);
    else if (highlights.length > 2) highlights = highlights.slice(0, -1);
    else combine = combine.slice(0, -1);
    text = parts(highlights, combine, routeLines);
  }
  return text.length <= FICHA_FACT_MAX_CHARS ? text : text.slice(0, FICHA_FACT_MAX_CHARS - 1).trimEnd();
}

export const CLAIM_FICHAS_MAX_CANDIDATES = 8;

export interface ClaimFichaV1 {
  readonly offering_code: string;
  readonly fact_id: string;
  readonly role: 'focus' | 'bonus_candidate';
  readonly value: string;
}

/** Only the course in focus and the current bonus candidates, never the 57. */
export function claimFichasV1(input: {
  readonly focusCode: string | null;
  readonly bonusCandidateCodes: readonly string[];
  readonly activeCodes: ReadonlySet<string>;
}): ClaimFichaV1[] {
  const render = (code: string, role: ClaimFichaV1['role']): ClaimFichaV1[] => {
    const value = fichaFactValueV1(code, { activeCodes: input.activeCodes });
    return value === null ? [] : [{ offering_code: code, fact_id: fichaFactIdV1(code), role, value }];
  };
  const candidates = [...new Set(input.bonusCandidateCodes)].filter((code) => code !== input.focusCode)
    .slice(0, CLAIM_FICHAS_MAX_CANDIDATES);
  return [
    ...(input.focusCode ? render(input.focusCode, 'focus') : []),
    ...candidates.flatMap((code) => render(code, 'bonus_candidate')),
  ];
}
